 "content": "def transform(grid):
    """Project the colors in the top-edge seed across their matching edge markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The colored cells along the top are parallel vertical rays. A matching
    # marker on either side edge turns that ray horizontally toward the marker;
    # otherwise the ray continues to the bottom edge.
    for col, color in enumerate(grid[0]):
        if color == 0:
            continue
        side_markers = [(r, 0) for r in range(h) if grid[r][0] == color]
        side_markers += [(r, w - 1) for r in range(h) if grid[r][w - 1] == color]
        if side_markers:
            # Inputs use one corresponding side marker for each seed color.
            r, edge_col = side_markers[0]
            for rr in range(min(0, r), max(0, r) + 1):
                out[rr][col] = color
            for cc in range(min(col, edge_col), max(col, edge_col) + 1):
                out[r][cc] = color
        else:
            for r in range(h):
                out[r][col] = color
    return out
